<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigRegisteredEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRegisteredEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withRegisteredEmail,
 * getRegisteredEmail/registeredEmail accessors, and isRegisteredEmailChanged with/without original.
 */
class TenantConfigRegisteredEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRegisteredEmail creates a new instance with the RegisteredEmail set
     * from a string value, and getRegisteredEmail returns the primitive string.
     */
    public function testWithRegisteredEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRegisteredEmailAccessorUnitTest();

        // Act
        $result = $holder->withRegisteredEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getRegisteredEmail());
    }
    /**
     * Asserts that withregisteredEmail has access to the value object
     * from a string value, and getRegisteredEmail returns the primitive string.
     */
    public function testWithRegisteredEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRegisteredEmailAccessorUnitTest();

        // Act
        $result = $holder->withRegisteredEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->registeredEmail()->value());
    }
    public function testChangedRegisteredEmail(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRegisteredEmailAccessorUnitTest();
        $original = $holder->withRegisteredEmail('one');
        $same = $holder->withRegisteredEmail('one');
        $modified = $holder->withRegisteredEmail('other');

        // Act
        $unchanged = $holder->isRegisteredEmailChanged();
        $withSame = $original->isRegisteredEmailChanged($same);
        $withDiferent = $original->isRegisteredEmailChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigRegisteredEmailAccessorUnitTest
{
    use TenantConfigRegisteredEmailAccessor;
}
